/**
 * explore 会话 hook（来源侧）：内部改走统一会话基建 use-agent-chat——
 * 重放装载（会话域查询 + 全史转录）/ 会话参数组装 / 运行门闩 / 停止接线
 * 全部由基建承担，本 hook 只保留 explore 侧语义：stance 前导拼接
 * （buildExplorePrompt）与来源三元组（source="explore"、sourceRef=记录 id
 * 十进制串）。对外状态语义（双恢复 / 续话 / running / error）与迁移前一致，
 * 另增停止透传；对外返回形状不回退（AC-11 承载面）。
 */

import { useCallback } from 'react';

import { useAgentChat } from '../../../hooks/use-agent-chat';
import { buildExplorePrompt } from '../../../lib/explore-stance';
import type { AgentPermissionMode, ExploreRecord } from '../../../types/dto';

/** explore 会话来源受控字符串（与 store 侧来源归属口径一致） */
const EXPLORE_SOURCE = 'explore';

/** 单次发送入参（与调试页表单语义一致：cwd 隐含 workspace root） */
export interface ExploreSendInput {
  prompt: string;
  permissionMode: AgentPermissionMode;
}

/**
 * 会话 hook（对话区数据面）：mount / 记录变更经基建重放装载（最新会话 +
 * 全史密封转录重放，重开双恢复的对话半边）；send 拼 stance 后委托基建，以
 * 当前会话（early-resolve 轮行回写的会话 id）Continue 续话、无会话 New；
 * 轮终态 record 部件回流后轮序列推进（下次续话以当前会话为准）。运行中防
 * 重复发送，record 为 null（未选定记录）不发送。记录级联删除随会话域级联
 * （`delete_explore_record` 会话归属圈定，转录与轮统计行同事务删）。
 */
export function useExploreSession(root: string | null, record: ExploreRecord | null) {
  const session = useAgentChat({
    source: EXPLORE_SOURCE,
    sourceRef: record !== null ? String(record.id) : null,
    root,
  });

  /** 发送一条消息：拼 stance、委托基建（会话参数组装在基建内收口）；record 为 null（未选定记录）不发送 */
  const send = useCallback(
    (input: ExploreSendInput) => {
      if (record === null) return;
      session.sendMessage({
        prompt: buildExplorePrompt(input.prompt),
        permissionMode: input.permissionMode,
      });
    },
    [session, record],
  );

  return {
    messages: session.messages,
    /** 轮统计行镜像（发起序轮行；迁移基线沿用，供既有断言与调试） */
    chain: session.chain,
    /** 密封事件扁平镜像（delta 仅实时流可见不入镜像；迁移基线沿用） */
    events: session.events,
    loading: session.loading,
    running: session.running,
    error: session.error,
    send,
    stop: session.stop,
  };
}

